/**
 * JobStatus is the lifecycle state of a job. queued and running are active;
 * the others are terminal.
 */
export const JobStatusQueued = "queued";
export const JobStatusRunning = "running";
export const JobStatusSuccess = "success";
export const JobStatusError = "error";
export const JobStatusCancelled = "cancelled";
/**
 * Job statuses.
 */
export type JobStatus = typeof JobStatusQueued | typeof JobStatusRunning | typeof JobStatusSuccess | typeof JobStatusError | typeof JobStatusCancelled;
/**
 * SubjectType is the kind of resource a job acts on. At most one job per
 * (subject_type, subject_id) is active at a time.
 */
export const SubjectTypeProject = "project";
export const SubjectTypeServer = "server";
/**
 * SubjectTypeCertificate is the installation's automatic (ACME)
 * certificates as a whole; its subject id is "acme".
 */
export const SubjectTypeCertificate = "certificate";
/**
 * Subject types.
 */
export type SubjectType = typeof SubjectTypeProject | typeof SubjectTypeServer | typeof SubjectTypeCertificate;
/**
 * JobKind names what a job does. New kinds may be added; clients should
 * display unknown kinds verbatim.
 */
export const JobKindProjectClone = "project.clone";
export const JobKindProjectPull = "project.pull";
export const JobKindProjectBranch = "project.branch";
export const JobKindProjectBuild = "project.build";
export const JobKindServerStart = "server.start";
export const JobKindServerStop = "server.stop";
export const JobKindServerRestart = "server.restart";
export const JobKindServerDelete = "server.delete";
/**
 * JobKindCertificateIssue obtains the certificates a mode change to
 * "acme" needs and then commits that change; JobKindCertificateRenew
 * replaces every managed certificate now. Both are restricted (admin).
 */
export const JobKindCertificateIssue = "certificate.issue";
export const JobKindCertificateRenew = "certificate.renew";
/**
 * Job kinds.
 */
export type JobKind = typeof JobKindProjectClone | typeof JobKindProjectPull | typeof JobKindProjectBranch | typeof JobKindProjectBuild | typeof JobKindServerStart | typeof JobKindServerStop | typeof JobKindServerRestart | typeof JobKindServerDelete | typeof JobKindCertificateIssue | typeof JobKindCertificateRenew;
/**
 * Job is a long-running operation. Routes that start one respond 202 with the
 * Job; poll GET /api/v1/jobs/{id} or stream GET /api/v1/jobs/{id}/log?follow=1.
 */
export interface Job {
  id: number /* int64 */;
  kind: JobKind;
  subject_type: SubjectType;
  /**
   * SubjectID is the subject's id rendered as a string (e.g. "12").
   */
  subject_id: string;
  status: JobStatus;
  /**
   * Detail is a short, user-safe outcome message for terminal jobs (empty on
   * success). Full output is in the job log.
   */
  detail: string;
  /**
   * Restricted jobs were started from an admin route: only admin sessions
   * can read their log or cancel them. Other jobs' logs are readable by any
   * developer; they can be cancelled by their creator or an admin.
   */
  restricted: boolean;
  /**
   * CreatedBy is the account that started the job; null for system jobs or
   * when that account was deleted.
   */
  created_by: number | null;
  /**
   * CreatedByUsername is the creator's username when the job is read;
   * null when CreatedBy is null.
   */
  created_by_username: string | null;
  created_at: string /* RFC 3339, UTC */;
  started_at: string | null;
  finished_at: string | null;
}
/**
 * JobList is the body of GET /api/v1/jobs, newest first.
 */
export interface JobList {
  items: Job[];
}

